from torch.utils.cpp_extension import load_inline

# CUDA kernel source
cuda_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv3d_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    const int batch,
    const int in_channels,
    const int out_channels,
    const int in_d,
    const int in_h,
    const int in_w,
    const int out_d,
    const int out_h,
    const int out_w,
    const int kD,
    const int kH,
    const int kW,
    const int stride,
    const int padding,
    const int dilation,
    const int groups)
{
    const int total = batch * out_channels * out_d * out_h * out_w;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride_grid = gridDim.x * blockDim.x;

    const int ic_per_group = in_channels / groups;
    const int oc_per_group = out_channels / groups;

    for (; idx < total; idx += stride_grid) {
        // decode linear index into N, OC, D, H, W
        int tmp = idx;
        const int w = tmp % out_w;        tmp /= out_w;
        const int h = tmp % out_h;        tmp /= out_h;
        const int d = tmp % out_d;        tmp /= out_d;
        const int oc = tmp % out_channels; tmp /= out_channels;
        const int n = tmp;  // batch index

        // determine group and relative channel indices
        const int g = oc / oc_per_group;
        const int ic_start = g * ic_per_group;
        const int oc_rel = oc - g * oc_per_group;   // 0 .. oc_per_group-1

        float sum = 0.0f;

        // convolution sum over input channels and kernel spatial dimensions
        for (int ic_rel = 0; ic_rel < ic_per_group; ++ic_rel) {
            const int ic = ic_start + ic_rel;
            for (int kd = 0; kd < kD; ++kd) {
                const int id = d * stride - padding + kd * dilation;
                if (id < 0 || id >= in_d) continue;
                for (int kh = 0; kh < kH; ++kh) {
                    const int ih = h * stride - padding + kh * dilation;
                    if (ih < 0 || ih >= in_h) continue;
                    for (int kw = 0; kw < kW; ++kw) {
                        const int iw = w * stride - padding + kw * dilation;
                        if (iw < 0 || iw >= in_w) continue;

                        // input linear index: (n, ic, id, ih, iw)
                        const int input_idx = (((((n * in_channels + ic) * in_d + id) * in_h + ih) * in_w) + iw);

                        // weight linear index: (oc_rel, ic_rel, kd, kh, kw)
                        const int weight_idx = ((((((oc_rel * ic_per_group) + ic_rel) * kD + kd) * kH + kh) * kW + kw);

                        float i_val = __half2float(input[input_idx]);
                        float w_val = __half2float(weight[weight_idx]);
                        sum += i_val * w_val;
                    }
                }
            }
        }

        // add bias if present
        if (bias != nullptr) {
            sum += __half2float(bias[oc]);
        }

        output[idx] = __float2half(sum);
    }
}

torch::Tensor conv3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    const int batch = input.size(0);
    const int in_channels = input.size(1);
    const int in_d = input.size(2);
    const int in_h = input.size(3);
    const int in_w = input.size(4);

    const int out_channels = weight.size(0);
    const int kD = weight.size(2);
    const int kH = weight.size(3);
    const int kW = weight.size(4);

    const int out_d = (int)std::floor((in_d + 2 * padding - dilation * (kD - 1) - 1) / stride + 1);
    const int out_h = (int)std::floor((in_h + 2 * padding - dilation * (kH - 1) - 1) / stride + 1);
    const int out_w = (int)std::floor((in_w + 2 * padding - dilation * (kW - 1) - 1) / stride + 1);

    auto output = torch::empty({batch, out_channels, out_d, out_h, out_w}, input.options());

    const int threads = 256;
    const int total = batch * out_channels * out_d * out_h * out_w;
    const int blocks = (total + threads - 1) / threads;

    const __half* bias_ptr = (bias.defined() && bias.numel() > 0)
        ? reinterpret_cast<const __half*>(bias.data_ptr<at::Half>())
        : nullptr;

    conv3d_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        bias_ptr,
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        batch,
        in_channels,
        out_channels,
        in_d, in_h, in_w,
        out_d, out_h, out_w,
        kD, kH, kW,
        stride,
        padding,
        dilation,
        groups
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }

    return output;
}
'''

